public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate inputs
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }
    if (start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    // Use only the first element when start/end are single‑int arrays (node indices)
    int startNode = start[0];
    int endNode = end[0];

    // Basic bounds check
    if (startNode < 0 || startNode >= n || endNode < 0 || endNode >= n) {
        return "cannot be travelled";
    }

    // Build adjacency list
    List<List<Integer>> adjacency = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        adjacency.add(new ArrayList<>());
    }
    for (int[] edge : paths) {
        if (edge == null || edge.length < 2) {
            continue; // ignore malformed edge
        }
        int u = edge[0];
        int v = edge[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            continue; // skip out of bounds edges
        }
        adjacency.get(u).add(v);
        adjacency.get(v).add(u); // assuming undirected graph; comment out if directed
    }

    // BFS to check reachability
    boolean[] visited = new boolean[n];
    Queue<Integer> queue = new ArrayDeque<>();
    queue.offer(startNode);
    visited[startNode] = true;

    while (!queue.isEmpty()) {
        int curr = queue.poll();
        if (curr == endNode) {
            return "can be travelled";
        }
        for (int neighbour : adjacency.get(curr)) {
            if (!visited[neighbour]) {
                visited[neighbour] = true;
                queue.offer(neighbour);
            }
        }
    }
    return "cannot be travelled";
}

public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        return null;
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        return "Invalid input format";
    }
    try {
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);
        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
        java.time.format.TextStyle full = java.time.format.TextStyle.FULL;
        java.util.Locale locale = java.util.Locale.ENGLISH;
        String monthName = localDate.getMonth().getDisplayName(full, locale);
        String weekday = localDate.getDayOfWeek().getDisplayName(full, locale);
        return String.format("%s %d, %d is a %s", monthName, day, year, weekday);
    } catch (Exception e) {
        return "Invalid date";
    }
}

public int[] twoSum(int[] nums, int target) {
    if (nums == null || nums.length < 2) {
        return new int[] {-1, -1};
    }
    java.util.HashMap<Integer, Integer> map = new java.util.HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        Integer j = map.get(complement);
        if (j != null) {
            return new int[] {j, i};
        }
        map.put(nums[i], i);
    }
    return new int[] {-1, -1};
}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        // Determine which side is sorted
        if (nums[left] <= nums[mid]) { // left side is sorted
            if (nums[left] <= target && target < nums[mid]) {
                right = mid - 1; // target in left side
            } else {
                left = mid + 1; // target in right side
            }
        } else { // right side is sorted
            if (nums[mid] < target && target <= nums[right]) {
                left = mid + 1; // target in right side
            } else {
                right = mid - 1; // target in left side
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int m = (int) Math.floor(n * 0.05);
    if (m * 2 >= n) {
        return 0.0; // not enough elements to compute mean
    }
    java.util.Arrays.sort(arr);
    long sum = 0;
    for (int i = m; i < n - m; i++) {
        sum += arr[i];
    }
    int count = n - 2 * m;
    return sum / (double) count;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        return false;
    }
    if (arr.length % 2 != 0) {
        return false;
    }

    int[] remainderCount = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        remainderCount[r]++;
    }

    // Remainder 0 must be even
    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    for (int r = 1; r < k; r++) {
        int complement = k - r;
        if (complement == r) { // occurs only when k is even and r == k/2
            if (remainderCount[r] % 2 != 0) {
                return false;
            }
        } else if (r < complement) { // check each pair only once
            if (remainderCount[r] != remainderCount[complement]) {
                return false;
            }
        }
    }
    return true;
}

