private int dfs(int node, int parent, List<Integer>[] adj, boolean[] hasApple) {
    int total = 0;
    for (int child : adj[node]) {
        if (child == parent) {
            continue;
        }
        int childCost = dfs(child, node, adj, hasApple);
        if (childCost > 0 || hasApple[child]) {
            total += childCost + 2;
        }
    }
    return total;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    java.util.TreeMap<Character, Integer> charCounts = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        charCounts.merge(c, 1, Integer::sum);
    }

    StringBuilder result = new StringBuilder();

    try {
        while (!charCounts.isEmpty()) {
            // Ascending pass
            Character prev = null;
            while (true) {
                Character nextKey = (prev == null) ? charCounts.firstKey()
                                                  : charCounts.higherKey(prev);
                if (nextKey == null) {
                    break;
                }
                result.append(nextKey);
                int newCount = charCounts.get(nextKey) - 1;
                if (newCount == 0) {
                    charCounts.remove(nextKey);
                } else {
                    charCounts.put(nextKey, newCount);
                }
                prev = nextKey;
            }

            if (charCounts.isEmpty()) {
                break;
            }

            // Descending pass
            Character prevDesc = charCounts.lastKey();
            result.append(prevDesc);
            int newCountDesc = charCounts.get(prevDesc) - 1;
            if (newCountDesc == 0) {
                charCounts.remove(prevDesc);
            } else {
                charCounts.put(prevDesc, newCountDesc);
            }
            prev = prevDesc;

            while (true) {
                Character nextKey = charCounts.lowerKey(prev);
                if (nextKey == null) {
                    break;
                }
                result.append(nextKey);
                int newCount = charCounts.get(nextKey) - 1;
                if (newCount == 0) {
                    charCounts.remove(nextKey);
                } else {
                    charCounts.put(nextKey, newCount);
                }
                prev = nextKey;
            }
        }
    } catch (Exception e) {
        // In case of any runtime exception, return the original string
        return s;
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }
    long totalSum = 0;
    for (int v : nums) {
        totalSum += v;
    }
    int m1 = n / 2;
    int m2 = n - m1;

    // Generate subset sums for the left half
    java.util.Map<Integer, java.util.Set<Long>> leftSums = new java.util.HashMap<>();
    for (int mask = 0; mask < (1 << m1); mask++) {
        int cnt = Integer.bitCount(mask);
        long sum = 0;
        for (int i = 0; i < m1; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[i];
            }
        }
        leftSums.computeIfAbsent(cnt, k -> new java.util.HashSet<>()).add(sum);
    }

    // Generate subset sums for the right half
    java.util.Map<Integer, java.util.Set<Long>> rightSums = new java.util.HashMap<>();
    for (int mask = 0; mask < (1 << m2); mask++) {
        int cnt = Integer.bitCount(mask);
        long sum = 0;
        for (int i = 0; i < m2; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[m1 + i];
            }
        }
        rightSums.computeIfAbsent(cnt, k -> new java.util.HashSet<>()).add(sum);
    }

    // Check possible subset sizes
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue;
        }
        long target = (totalSum * k) / n;
        int minC1 = Math.max(0, k - m2);
        int maxC1 = Math.min(k, m1);
        for (int c1 = minC1; c1 <= maxC1; c1++) {
            java.util.Set<Long> set1 = leftSums.get(c1);
            java.util.Set<Long> set2 = rightSums.get(k - c1);
            if (set1 == null || set2 == null) {
                continue;
            }
            for (Long sum1 : set1) {
                long need = target - sum1;
                if (set2.contains(need)) {
                    return true;
                }
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) return 0;
    int n = cost.length;
    if (n == 1) return Math.min(cost[0], 0);
    int prevPrev = 0; // dp[0]
    int prev = 0;     // dp[1]
    int current = 0;
    for (int i = 2; i <= n; i++) {
        int costPrev = (i - 1 < n) ? cost[i - 1] + prev : Integer.MAX_VALUE;
        int costPrevPrev = (i - 2 < n) ? cost[i - 2] + prevPrev : Integer.MAX_VALUE;
        current = Math.min(costPrev, costPrevPrev);
        prevPrev = prev;
        prev = current;
    }
    return current;
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null || words.length == 0) {
        return 0;
    }

    String[] morse = {
        ".-", "-...", "-.-.", "-..", ".", "..-.", "--.", "....", "..",
        ".---", "-.-", ".-..", "--", "-.", "---", ".--.", "--.-", ".-.",
        "...", "-", "..-", "...-", ".--", "-..-", "-.--", "--.."
    };

    Set<String> uniqueSet = new HashSet<>();

    for (String word : words) {
        if (word == null) {
            continue; // skip null entries if present
        }
        StringBuilder transformed = new StringBuilder();
        for (char c : word.toCharArray()) {
            // Only consider lowercase letters a-z
            if (c >= 'a' && c <= 'z') {
                transformed.append(morse[c - 'a']);
            }
            // If uppercase letters are possible, include mapping similarly
            else if (c >= 'A' && c <= 'Z') {
                transformed.append(morse[c - 'A']);
            }
            // Non-alphabetic characters are ignored as per problem definition
        }
        uniqueSet.add(transformed.toString());
    }

    return uniqueSet.size();
}

public boolean hasAllCodes(String s, int k) {
    if (k <= 0) return true;
    int n = s.length();
    if (n < k) return false;

    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int count = 0;
    int mask = total - 1;
    int code = 0;

    for (int i = 0; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[code]) {
                seen[code] = true;
                count++;
                if (count == total) {
                    return true;
                }
            }
        }
    }
    return false;
}

public int isPrefixOfWord(String sentence, String searchWord) {
