        return -1;
    }
    // Split sentence into words by whitespace
    String[] words = sentence.trim().split("\\s+");
    // Iterate through words to find first prefix match
    for (int i = 0; i < words.length; i++) {
        if (words[i].startsWith(searchWord)) {
            return i + 1; // 1‑based index
        }
    }
    return -1; // no match found
}

public int minInsertions(String s) {
    if (s == null) {
        return 0;
    }
    int insertions = 0;
    int unmatchedOpen = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            unmatchedOpen++;
        } else if (c == ')') {
            if (unmatchedOpen > 0) {
                unmatchedOpen--;
            } else {
                // Need an opening parenthesis before this ')'
                insertions++;
            }
        }
    }
    // Remaining unmatched '(' need ')' to balance each
    insertions += unmatchedOpen;
    return insertions;
}

public int highestAltitude(int[] gain) {
