        if (currentAltitude > maxAltitude) {
            maxAltitude = currentAltitude;
        }
    }
    return maxAltitude;
}

public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxEnding = nums[0];
    int maxSum = nums[0];
    int minEnding = nums[0];
    int minSum = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int num = nums[i];
        maxEnding = Math.max(num, maxEnding + num);
        maxSum = Math.max(maxSum, maxEnding);
        minEnding = Math.min(num, minEnding + num);
        minSum = Math.min(minSum, minEnding);
    }
    return Math.max(maxSum, Math.abs(minSum));
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer");
    }
    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int next = fibs.get(fibs.size() - 1) + fibs.get(fibs.size() - 2);
        if (next > k) {
            break;
        }
        fibs.add(next);
    }
    // Greedy approach: subtract the largest Fibonacci number repeatedly
    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int fib = fibs.get(i);
        while (remaining >= fib) {
            remaining -= fib;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    // Validate input
    if (n <= 0 || k <= 0) {
        return -1;
    }

    java.util.List<Integer> factors = new java.util.ArrayList<>();

    // Find all divisors
    for (int i = 1; (long) i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            int complement = n / i;
            if (complement != i) {
                factors.add(complement);
            }
        }
    }

    // Sort in ascending order
    java.util.Collections.sort(factors);

    // Return kth factor or -1 if not enough factors
    if (k > factors.size()) {
        return -1;
    }
    return factors.get(k - 1);
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char last = stack.charAt(len - 1);
            if (Math.abs(c - last) == 32) { // same letter but different case
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) return 0;
    class Solver {
        int max = 0;
        void dfs(int idx, Set<String> used) {
            if (idx == s.length()) {
                max = Math.max(max, used.size());
                return;
            }
            for (int end = idx + 1; end <= s.length(); end++) {
                String sub = s.substring(idx, end);
                if (!used.contains(sub)) {
                    used.add(sub);
                    dfs(end, used);
                    used.remove(sub);
                }
            }
        }
    }
    Solver solver = new Solver();
    solver.dfs(0, new HashSet<>());
    return solver.max;
}

