public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array cannot be null or empty");
    }
    int[] bitCounts = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            if ((num & (1 << i)) != 0) {
                bitCounts[i]++;
            }
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if ((bitCounts[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    if (low > high) {
        return new ArrayList<>();
    }

    List<Integer> result = new ArrayList<>();
    if (low == 0) {
        result.add(0);
    }

    Queue<Long> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }

    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }

        long lastDigit = num % 10;

        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }

    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0L;
    long i = 1L;
    while (i <= n) {
        long high = n / (i * 10);
        int curr = (int) ((n / i) % 10);
        long low = n % i;
        if (curr > 1) {
            count += (high + 1) * i;
        } else if (curr == 1) {
            count += high * i + low + 1;
        } else {
            count += high * i;
        }
        i *= 10;
    }
    return (int) count;
}

