public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] horizontal = new int[m][n];
    int[][] vertical = new int[m][n];
    int[][] diagonal = new int[m][n];
    int[][] antiDiagonal = new int[m][n];
    int maxLen = 0;

    try {
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 1) {
                    horizontal[i][j] = (j > 0 ? horizontal[i][j - 1] : 0) + 1;
                    vertical[i][j] = (i > 0 ? vertical[i - 1][j] : 0) + 1;
                    diagonal[i][j] = (i > 0 && j > 0 ? diagonal[i - 1][j - 1] : 0) + 1;
                    antiDiagonal[i][j] = (i > 0 && j < n - 1 ? antiDiagonal[i - 1][j + 1] : 0) + 1;
                    int localMax = Math.max(
                        Math.max(horizontal[i][j], vertical[i][j]),
                        Math.max(diagonal[i][j], antiDiagonal[i][j])
                    );
                    if (localMax > maxLen) {
                        maxLen = localMax;
                    }
                } else {
                    horizontal[i][j] = 0;
                    vertical[i][j] = 0;
                    diagonal[i][j] = 0;
                    antiDiagonal[i][j] = 0;
                }
            }
        }
    } catch (Exception e) {
        // In case of any runtime issues, return 0 as a safe fallback
        return 0;
    }

    return maxLen;
}

public static String addThousandSeparator(int n) {
    long value = n;
    boolean negative = value < 0;
    value = Math.abs(value);
    String numStr = Long.toString(value);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    for (int i = numStr.length() - 1; i >= 0; i--) {
        sb.append(numStr.charAt(i));
        count++;
        if (count == 3 && i != 0) {
            sb.append('.');
            count = 0;
        }
    }
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) {
        return 1;
    }
    java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
    for (int v : A) {
        freq.put(v, freq.getOrDefault(v, 0) + 1);
    }
    int[] count = new int[]{0};
    for (int key : new java.util.ArrayList<>(freq.keySet())) {
        int newCnt = freq.get(key) - 1;
        if (newCnt == 0) {
            freq.remove(key);
        } else {
            freq.put(key, newCnt);
        }
        backtrack(key, freq, n - 1, count);
        freq.put(key, freq.getOrDefault(key, 0) + 1);
    }
    return count[0];
}

private static void backtrack(int prev, java.util.HashMap<Integer, Integer> freq, int remaining, int[] count) {
    if (remaining == 0) {
        count[0]++;
        return;
    }
    for (int num : new java.util.ArrayList<>(freq.keySet())) {
        if (isSquare(prev + num)) {
            int newCnt = freq.get(num) - 1;
            if (newCnt == 0) {
                freq.remove(num);
            } else {
                freq.put(num, newCnt);
            }
            backtrack(num, freq, remaining - 1, count);
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }
    }
}

private static boolean isSquare(int x) {
    int r = (int) Math.sqrt(x);
    return r * r == x;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int maxArea = 0;
    java.util.Stack<Integer> stack = new java.util.Stack<>();

    for (int i = 0; i <= heights.length; i++) {
        int currentHeight = (i == heights.length) ? 0 : heights[i];

        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int leftBoundary = stack.isEmpty() ? 0 : stack.peek() + 1;
            int width = i - leftBoundary;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }

        stack.push(i);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int d = 0; d <= m + n - 2; d++) {
        if (d % 2 == 0) {
            int r = Math.min(d, m - 1);
            int c = d - r;
            while (r >= 0 && c < n) {
                result[idx++] = mat[r][c];
                r--;
                c++;
            }
        } else {
            int c = Math.min(d, n - 1);
            int r = d - c;
            while (c >= 0 && r < m) {
                result[idx++] = mat[r][c];
                r++;
                c--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) return -1;
    char[] digits = String.valueOf(n).toCharArray();
    int len = digits.length;

    // Find the pivot: first index from the right where digits[i] < digits[i+1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) return -1; // No higher permutation exists

    // Find the rightmost successor to the pivot that is greater than digits[i]
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap pivot with successor
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the suffix starting at i+1 to get the smallest ordering
    int left = i + 1, right = len - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }

    // Convert back to integer, checking for overflow
    long result = 0;
    for (char c : digits) {
        result = result * 10 + (c - '0');
        if (result > Integer.MAX_VALUE) return -1;
    }
    return (int) result;
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Length cannot be negative");
    }
    if (n == 0) {
        return new ArrayList<>();
    }
    List<String> result = generateStrobogrammatic(n, n);
    // Remove numbers with leading zero when length > 1
    if (n > 1) {
        Iterator<String> it = result.iterator();
        while (it.hasNext()) {
            String s = it.next();
            if (s.charAt(0) == '0') {
                it.remove();
            }
        }
    }
    return result;
}

private static List<String> generateStrobogrammatic(int remaining, int totalLen) {
    if (remaining == 0) {
        List<String> base = new ArrayList<>();
        base.add("");
        return base;
    }
    if (remaining == 1) {
        List<String> mid = new ArrayList<>();
        mid.add("0");
        mid.add("1");
        mid.add("8");
        return mid;
    }
    List<String> prev = generateStrobogrammatic(remaining - 2, totalLen);
    List<String> result = new ArrayList<>();
    char[][] pairs = { {'0','0'}, {'1','1'}, {'6','9'}, {'8','8'}, {'9','6'} };
    for (String middle : prev) {
        for (char[] p : pairs) {
            result.add(p[0] + middle + p[1]);
        }
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    // Validate input
    if (points == null || points.length != 3) {
        return false;
    }
    // Ensure each point has exactly two coordinates and is not null
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }
    int[] p1 = points[0];
    int[] p2 = points[1];
    int[] p3 = points[2];

    // Check that all points are distinct
    if ((p1[0] == p2[0] && p1[1] == p2[1]) ||
        (p1[0] == p3[0] && p1[1] == p3[1]) ||
        (p2[0] == p3[0] && p2[1] == p3[1])) {
        return false;
    }

    // Compute the cross product to determine collinearity
    long cross = (long) (p2[0] - p1[0]) * (p3[1] - p1[1])
               - (long) (p2[1] - p1[1]) * (p3[0] - p1[0]);

    // Non-zero cross product means the points are not collinear
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        // Return -1 for invalid input to avoid exceptions
        return -1;
    }

    // Use long for intermediate calculations to reduce overflow risk
    long[] ugly = new long[n];
    ugly[0] = 1L;

    int i2 = 0, i3 = 0, i5 = 0;
    long next2 = 2L, next3 = 3L, next5 = 5L;

    for (int i = 1; i < n; i++) {
        long nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;

        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2L;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3L;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5L;
        }
    }

    return (int) ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int max = 1;
    int current = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            current++;
        } else {
            if (current > max) {
                max = current;
            }
            current = 1;
        }
    }
    return Math.max(max, current);
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int curr = 1;
    for (int i = 0; i < n; i++) {
        result.add(curr);
        if ((long) curr * 10 <= n) {
            curr *= 10;
        } else {
            while (curr % 10 == 9 || curr + 1 > n) {
                curr /= 10;
            }
            curr++;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int n : nums) {
        freq.put(n, freq.getOrDefault(n, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        int sqrt = (int) Math.sqrt(i);
        for (int j = 1; j <= sqrt; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < min) {
                min = dp[i - square] + 1;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder current = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            current.reverse();              // reverse the accumulated word
            result.append(current);         // append reversed word
            current.setLength(0);           // reset for next word
            result.append(c);               // keep the space
        } else {
            current.append(c);              // build the word
        }
    }
    // Append the last word after the loop
    current.reverse();
    result.append(current);
    return result.toString();
}
